// i18n léger et partagé pour les fenêtres secondaires (Agents, Sandbox, Kanban,
// Workspace) qui sont écrites en français en dur. Si la langue de l'app est
// l'anglais, on traduit le DOM (textes, placeholder/title/value) au chargement,
// et `tt()` traduit les chaînes générées dynamiquement.
//
// La langue est partagée avec la fenêtre principale via localStorage("lang").

export function appLang() {
  return localStorage.getItem("lang")
    || ((navigator.language || "fr").toLowerCase().startsWith("en") ? "en" : "fr");
}

