// Traduit une chaîne FR (chaînes dynamiques). Renvoie l'original si pas de
// traduction ou si la langue est le français.
/// Dictionnaire propre à une app (clé = texte français exact, valeur = anglais).
/// Les apps récentes gardent leurs libellés dans leur propre `i18n.js` plutôt
/// que dans ce fichier déjà très long ; elles l'enregistrent au chargement,
/// AVANT le premier `tt()` ou `autoTranslate()`.
export function registerTranslations(dict) {
  for (const [fr, en] of Object.entries(dict || {})) if (en) EN[fr] = en;
}

export function tt(fr, vars = {}) {
  const base = appLang() !== "en" ? fr : (EN[fr] != null ? EN[fr] : fr);
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.replaceAll(`{${k}}`, String(v)),
    base,
  );
}

// Traduit un attribut connu sur un élément.
function translateAttrs(el) {
  if (!el.getAttribute) return;
  for (const a of ["placeholder", "title", "value", "aria-label"]) {
    const v = el.getAttribute(a);
    if (v && EN[v.trim()]) el.setAttribute(a, EN[v.trim()]);
  }
}

// Traduit un seul nœud texte s'il correspond exactement à une clé connue.
function translateTextNode(n) {
  const p = n.parentNode && n.parentNode.nodeName;
  if (p === "SCRIPT" || p === "STYLE" || p === "svg" || p === "SVG") return;
  if (!n.nodeValue || !n.nodeValue.trim()) return;
  const t = n.nodeValue.trim();
  if (EN[t]) n.nodeValue = n.nodeValue.replace(t, EN[t]);
}

// Traduit un sous-arbre (élément ou document) : attributs + nœuds texte.
// Ne remplace que des chaînes exactement présentes dans le dictionnaire —
// jamais des données (nombres, texte utilisateur…), qui n'y figurent pas.
export function translateTree(root) {
  if (appLang() !== "en" || !root) return;
  if (root.nodeType === Node.TEXT_NODE) { translateTextNode(root); return; }
  if (root.querySelectorAll) {
    if (root.nodeType === Node.ELEMENT_NODE) translateAttrs(root);
    root.querySelectorAll("[placeholder],[title],[value],[aria-label]").forEach(translateAttrs);
  }
  const scope = root.nodeType === Node.DOCUMENT_NODE ? root : root;
  const walk = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, {
    acceptNode(n) {
      return n.nodeValue && n.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    },
  });
  const nodes = [];
  while (walk.nextNode()) nodes.push(walk.currentNode);
  nodes.forEach(translateTextNode);
}

// Traduit le DOM statique d'une page (textes, placeholder/title/value).
export function translatePage(root = document) {
  translateTree(root);
}

// Installe un observateur qui traduit les nœuds ajoutés dynamiquement.
// Utile pour les apps qui rendent leur contenu en JS après le chargement.
export function observeTranslations(root = document.body) {
  if (appLang() !== "en" || !root || typeof MutationObserver === "undefined") return null;
  const obs = new MutationObserver((records) => {
    for (const r of records) {
      for (const node of r.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE || node.nodeType === Node.TEXT_NODE) translateTree(node);
      }
    }
  });
  obs.observe(root, { childList: true, subtree: true });
  return obs;
}

// Pratique : applique la traduction de page au chargement du DOM.
// Passer { observe: true } pour aussi traduire le contenu rendu ensuite en JS.
export function autoTranslate(opts = {}) {
  const run = () => {
    translatePage();
    if (opts.observe) observeTranslations();
  };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run);
  else run();
}
